-- Run after 03_connected_demo_scenarios.sql in the separate demo project.
-- Source: the user's metadata and BOM CSVs. Source dates/IDs/customer links are excluded.
-- Stock balances are explicitly sample quantities, not actual warehouse stock.
begin;
do $$ begin
 if to_regprocedure('public.seed_demo_scenarios()') is null then raise exception 'Run 03_connected_demo_scenarios.sql first';end if;
end $$;
create table if not exists public.inventory_items(
 id uuid primary key default gen_random_uuid(),demo_session_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
 item_key text not null,sku text not null,product_name text not null,uom text not null,
 stock_on_hand numeric(14,3) not null default 0 check(stock_on_hand>=0),reorder_level numeric(14,3) not null default 0 check(reorder_level>=0),
 created_at timestamptz not null default now(),unique(demo_session_id,item_key),unique(demo_session_id,sku),unique(id,demo_session_id)
);
create table if not exists public.inventory_movements(
 id uuid primary key default gen_random_uuid(),demo_session_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
 item_id uuid not null,request_id uuid not null,kind text not null check(kind in ('opening','receipt','issue')),
 quantity numeric(14,3) not null check(quantity>0),note text not null,created_at timestamptz not null default now(),
 unique(demo_session_id,request_id),foreign key(item_id,demo_session_id) references public.inventory_items(id,demo_session_id)
);
do $$ declare t text;begin
 foreach t in array array['inventory_items','inventory_movements'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from anon',t);
  execute format('grant select,insert,update on public.%I to authenticated',t);
  execute format('drop policy if exists inventory_sandbox on public.%I',t);
  execute format('create policy inventory_sandbox on public.%I to authenticated using(demo_session_id=(select auth.uid())) with check(demo_session_id=(select auth.uid()))',t);
 end loop;
end $$;
alter table public.admin add column if not exists bom_data jsonb;
alter table public.profiles add column if not exists inventory_reference_version integer not null default 0;
create or replace function public.inventory_item_key(p_name text,p_unit text)
returns text language sql immutable set search_path='' as $$
 select (case regexp_replace(lower(trim(p_name)),'\s+',' ','g') when '16sq mm la cabel' then '16sq mm la cable' when 'condute pipe' then 'conduite pipe' else regexp_replace(lower(trim(p_name)),'\s+',' ','g') end)
 ||'|'||(case when lower(trim(p_unit)) in ('no.','nos','no','nos.') then 'Nos' else trim(p_unit) end);
$$;
create or replace function public.sync_inventory_catalog()
returns void language sql security invoker set search_path='' as $$
 insert into public.inventory_items(item_key,sku,product_name,uom)
 select distinct on(public.inventory_item_key(product_name,uom)) public.inventory_item_key(product_name,uom),
 'BOM-'||substr(md5(public.inventory_item_key(product_name,uom)),1,12),product_name,
 case when lower(trim(uom)) in ('no.','nos','no','nos.') then 'Nos' else trim(uom) end
 from public.bom_items where demo_session_id=auth.uid() and nullif(trim(uom),'') is not null
 and product_name<>'SolarFlow Demo Panel'
 on conflict(demo_session_id,item_key) do nothing;
$$;
create or replace function public.record_inventory_movement(p_item_id uuid,p_kind text,p_quantity numeric,p_note text,p_request_id uuid)
returns public.inventory_items language plpgsql security invoker set search_path='' as $$
declare item public.inventory_items; previous public.inventory_movements;begin
 if auth.uid() is null then raise exception 'Sign in to the demo first';end if;
 if p_kind not in ('receipt','issue') or p_kind is null or p_quantity is null or p_quantity<=0 or p_quantity::text in ('NaN','Infinity','-Infinity') or p_quantity<>round(p_quantity,3) then raise exception 'Use a positive quantity with at most three decimal places';end if;
 if nullif(trim(p_note),'') is null or length(p_note)>500 or p_request_id is null then raise exception 'A note and request ID are required';end if;
 select * into item from public.inventory_items where id=p_item_id and demo_session_id=auth.uid() for update;
 if not found then raise exception 'Inventory item unavailable';end if;
 select * into previous from public.inventory_movements where demo_session_id=auth.uid() and request_id=p_request_id;
 if found then
  if previous.item_id<>p_item_id or previous.kind<>p_kind or previous.quantity<>p_quantity or previous.note<>trim(p_note) then raise exception 'Request ID already used for another movement';end if;
  return item;
 end if;
 if p_kind='issue' and item.stock_on_hand<p_quantity then raise exception 'Insufficient stock: % % available',item.stock_on_hand,item.uom;end if;
 update public.inventory_items set stock_on_hand=stock_on_hand+(case when p_kind='issue' then -p_quantity else p_quantity end) where id=item.id returning * into item;
 insert into public.inventory_movements(item_id,request_id,kind,quantity,note)values(item.id,p_request_id,p_kind,p_quantity,trim(p_note));
 return item;
end $$;
