:"Earth Pit Doll","uom":"Nos","aliases":["Earth Pit Doll"],"bom_types":["ROOF"],"sku":"SF-MAT-033","opening_stock":0,"reorder_level":20},{"product_name":"40*40 Pipe Perlin","uom":"Feet","aliases":["40*40 Pipe Perlin"],"bom_types":["ROOF"],"sku":"SF-MAT-034","opening_stock":500,"reorder_level":40},{"product_name":"60*40 Pipe rafter","uom":"Feet","aliases":["60*40 Pipe rafter"],"bom_types":["ROOF"],"sku":"SF-MAT-035","opening_stock":20,"reorder_level":40},{"product_name":"60*40 front leg","uom":"Feet","aliases":["60*40 front leg"],"bom_types":["ROOF"],"sku":"SF-MAT-036","opening_stock":500,"reorder_level":40},{"product_name":"60*40 Rear leg","uom":"Feet","aliases":["60*40 Rear leg"],"bom_types":["ROOF"],"sku":"SF-MAT-037","opening_stock":500,"reorder_level":40},{"product_name":"LA  insuletar","uom":"Nos","aliases":["LA  insuletar"],"bom_types":["ROOF","SHED"],"sku":"SF-MAT-038","opening_stock":200,"reorder_level":20},{"product_name":"cabale tre","uom":"Nos","aliases":["cabale tre"],"bom_types":["ROOF","SHED"],"sku":"SF-MAT-039","opening_stock":200,"reorder_level":20},{"product_name":"Earthing Kit + LA","uom":"Nos","aliases":["Earthing Kit + LA"],"bom_types":["ROOF","SHED"],"sku":"SF-MAT-040","opening_stock":200,"reorder_level":20},{"product_name":"chemical","uom":"Nos","aliases":["chemical"],"bom_types":["ROOF","SHED"],"sku":"SF-MAT-041","opening_stock":200,"reorder_level":20},{"product_name":"Conduite Pipe","uom":"Nos","aliases":["Conduite Pipe","Condute Pipe"],"bom_types":["ROOF","SHED"],"sku":"SF-MAT-042","opening_stock":10,"reorder_level":20},{"product_name":"Cement","uom":"Bag","aliases":["Cement"],"bom_types":["ROOF"],"sku":"SF-MAT-043","opening_stock":30,"reorder_level":5},{"product_name":"Reti","uom":"Bag (50 kg)","aliases":["Reti"],"bom_types":["ROOF"],"sku":"SF-MAT-044","opening_stock":0,"reorder_level":5},{"product_name":"Kapachi","uom":"Bag (50 kg)","aliases":["Kapachi"],"bom_types":["ROOF"],"sku":"SF-MAT-045","opening_stock":30,"reorder_level":5},{"product_name":"Spring + HEX Bolt","uom":"Nos","aliases":["Spring + HEX Bolt"],"bom_types":["SHED"],"sku":"SF-MAT-046","opening_stock":200,"reorder_level":20},{"product_name":"L And Key","uom":"Nos","aliases":["L And Key"],"bom_types":["SHED"],"sku":"SF-MAT-047","opening_stock":200,"reorder_level":20},{"product_name":"80*40 J bolt mota","uom":"Nos","aliases":["80*40 J bolt mota"],"bom_types":["SHED"],"sku":"SF-MAT-048","opening_stock":200,"reorder_level":20},{"product_name":"Damar roll","uom":"MTR","aliases":["Damar roll"],"bom_types":["SHED"],"sku":"SF-MAT-049","opening_stock":10,"reorder_level":20},{"product_name":"Earthing ડોલ / ઢાંકણા","uom":"Nos","aliases":["Earthing ડોલ / ઢાંકણા"],"bom_types":["SHED"],"sku":"SF-MAT-050","opening_stock":200,"reorder_level":20},{"product_name":"C Chanel","uom":"Nos","aliases":["C Chanel"],"bom_types":["SHED"],"sku":"SF-MAT-051","opening_stock":200,"reorder_level":20},{"product_name":"Z mota","uom":"Nos","aliases":["Z mota"],"bom_types":["SHED"],"sku":"SF-MAT-052","opening_stock":200,"reorder_level":20},{"product_name":"Z nana","uom":"Nos","aliases":["Z nana"],"bom_types":["SHED"],"sku":"SF-MAT-053","opening_stock":200,"reorder_level":20}]}$ref$::jsonb; entry jsonb; v_category text; labels jsonb; v_label text;
 item public.inventory_items; c public.admin; b public.bom; scenario jsonb; line jsonb; kind text; n integer; wp integer; brand text;
begin
 perform public.seed_demo_scenarios();
 if (select inventory_reference_version from public.profiles where id=u)<4 then
  -- Renaming metadata invokes 03's synchronization trigger, preserving staff IDs/BOM links.
  update public.metadata set label='Demo Staff Cedar' where demo_session_id=u and category='integration_by' and label='Demo Preparer'
   and not exists(select 1 from public.metadata where demo_session_id=u and category='integration_by' and label='Demo Staff Cedar');
  update public.metadata set label='Demo Staff Maple' where demo_session_id=u and category='integration_by' and label='Demo Loader'
   and not exists(select 1 from public.metadata where demo_session_id=u and category='integration_by' and label='Demo Staff Maple');
  update public.metadata set label='Demo Staff Willow' where demo_session_id=u and category='integration_by' and label='Demo Installer'
   and not exists(select 1 from public.metadata where demo_session_id=u and category='integration_by' and label='Demo Staff Willow');
  for v_category,labels in select * from jsonb_each(reference->'metadata') loop
   for v_label in select jsonb_array_elements_text(labels) loop
    insert into public.metadata(category,label)values(v_category,v_label) on conflict(demo_session_id,category,label) do nothing;
   end loop;
  end loop;
  delete from public.metadata where demo_session_id=u and (
   (category='company_branch' and label ~ '^Demo Branch( [0-9]+)?$') or
   (category='module_brand' and label in ('SolarFlow Essential','SolarFlow Plus','SolarFlow Premium')) or
   (category='inverter_make' and label in ('DemoVolt','DemoGrid','DemoSun')));
  insert into public.metadata(category,label)
   select 'company_branch',value from jsonb_array_elements_text(reference->'metadata'->'registration_by') as r(value)
   where value ilike '%Office%' on conflict(demo_session_id,category,label) do nothing;
  -- Replace only untouched single-placeholder sample BOMs. Preserve edited/custom BOMs and inline snapshots.
  for c in select * from public.admin where demo_session_id=u and demo_seed_key like 'solarflow-50-v1-%' and (bom_data is null or bom_data='{}'::jsonb) loop
   n:=split_part(c.demo_seed_key,'-',4)::integer;
   for b in select * from public.bom where admin_id=c.id and demo_session_id=u and bom_type='ROOF' loop
    if (select count(*) from public.bom_items where bom_id=b.id)=1 and exists(select 1 from public.bom_items where bom_id=b.id and product_name='SolarFlow Demo Panel' and note='Synthetic sample item') then
     kind:=case when lower(c.roof_shed)='shed' then 'SHED' else 'ROOF' end;
     -- Keep the seeded ROOF record for compatibility; add the active SHED alternative when needed.
     if kind='SHED' then
      insert into public.bom(admin_id,bom_type)values(c.id,'SHED') on conflict(admin_id,bom_type) do nothing;
     end if;
     for kind in select unnest(case when lower(c.roof_shed)='shed' then array['ROOF','SHED'] else array['ROOF'] end) loop
      select * into b from public.bom where admin_id=c.id and demo_session_id=u and bom_type=kind;
      if (kind='ROOF') or not exists(select 1 from public.bom_items where bom_id=b.id) then
       scenario:=(reference->'scenarios'->kind)->((n-1)%jsonb_array_length(reference->'scenarios'->kind));
       delete from public.bom_items where bom_id=b.id and product_name='SolarFlow Demo Panel' and note='Synthetic sample item';
       for line in select jsonb_array_elements(scenario->'items') loop
        insert into public.bom_items(bom_id,sr_no,product_name,quantity,uom,integration_by,note,demo_seed_key)
        values(b.id,(line->>'sr_no')::integer,line->>'product_name',line->>'quantity',line->>'uom',nullif(line->>'integration_by',''),
         'Reference BOM quantities from supplied CSV; confirm for this project.',case when kind='ROOF' and (line->>'sr_no')::integer=1 then c.demo_seed_key else null end);
       end loop;
       update public.bom set paper_prepared_by=scenario->>'paper_prepared_by',material_loaded_by=scenario->>'material_loaded_by',paper_prepared_date=null,material_loaded_date=null where id=b.id;
      end if;
     end loop;
     scenario:=(reference->'scenarios'->(case when lower(c.roof_shed)='shed' then 'SHED' else 'ROOF' end))->((n-1)%3);
     wp:=(reference->'metadata'->'module_wp'->>((n-1)%jsonb_array_length(reference->'metadata'->'module_wp')))::integer;
     brand:=reference->'metadata'->'module_brand'->>((n-1)%jsonb_array_length(reference->'metadata'->'module_brand'));
     update public.admin set module_brand=brand,module_wp=wp,no_of_modules=(scenario->>'panel_count')::integer,
      system_capacity_kwp=wp*(scenario->>'panel_count')::numeric/1000,inverter_make=reference->'metadata'->'inverter_make'->>((n-1)%4)
      where id=c.id and module_brand='SolarFlow Essential';
    end if;
   end loop;
  end loop;
  for entry in select jsonb_array_elements(reference->'catalog') loop
   insert into public.inventory_items(item_key,sku,product_name,uom,stock_on_hand,reorder_level)
    values(public.inventory_item_key(entry->>'product_name',entry->>'uom'),entry->>'sku',entry->>'product_name',entry->>'uom',(entry->>'opening_stock')::numeric,(entry->>'reorder_level')::numeric)
    on conflict(demo_session_id,item_key) do nothing returning * into item;
   if found and item.stock_on_hand>0 then insert into public.inventory_movements(item_id,request_id,kind,quantity,note) values(item.id,gen_random_uuid(),'opening',item.stock_on_hand,'Sample opening stock — not an actual stock count');end if;
  end loop;
  update public.profiles set inventory_reference_version=4 where id=u;
 end if;
 delete from public.metadata where demo_session_id=u and (
  (category='company_branch' and label ~ '^Demo Branch( [0-9]+)?$') or
  (category='module_brand' and label in ('SolarFlow Essential','SolarFlow Plus','SolarFlow Premium')) or
  (category='inverter_make' and label in ('DemoVolt','DemoGrid','DemoSun')));
 -- The older seed can recreate its placeholder after a saved BOM replaced its rows.
 delete from public.bom_items placeholder where placeholder.demo_session_id=u
  and placeholder.product_name='SolarFlow Demo Panel' and placeholder.note='Synthetic sample item'
  and exists(select 1 from public.bom_items actual where actual.bom_id=placeholder.bom_id and actual.product_name<>'SolarFlow Demo Panel');
 perform public.sync_inventory_catalog();
end $$;
create or replace function public.start_demo_session(p_role text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare u uuid:=auth.uid(); r public.demo_roles; p public.profiles; d public.demo_profiles;
begin
 if u is null then raise exception 'Call signInAnonymously() first'; end if;
 select * into r from public.demo_roles where user_type=p_role;
 if not found then raise exception 'Unknown demo role'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 insert into public.profiles(id,demo_session_id,name,email,user_type,role,channel_partner)
 values(u,u,'Demo '||r.label,'demo.'||p_role||'@solarflow.example',p_role,r.role,'Demo Aurora Solar')
 on conflict(id) do update set user_type=excluded.user_type,role=excluded.role;
 perform public.seed_demo_inventory();
 select * into d from public.demo_profiles where demo_session_id=u and demo_profile_key=p_role and status='active';
 if not found then raise exception 'This demo role is inactive'; end if;
 update public.profiles set name=d.name,email=d.email,user_type=d.user_type,role=d.role,channel_partner=d.channel_partner,
 status=d.status,demo_profile_id=d.id where id=u returning * into p;
 return to_jsonb(p)||jsonb_build_object('userType',p.user_type,'isDemo',true);
end $$;
revoke all on function public.seed_demo_inventory(),public.sync_inventory_catalog(),public.record_inventory_movement(uuid,text,numeric,text,uuid),public.start_demo_session(text) from public,anon;
grant execute on function public.seed_demo_inventory(),public.sync_inventory_catalog(),public.record_inventory_movement(uuid,text,numeric,text,uuid),public.start_demo_session(text) to authenticated;
do $$ declare p record; old_uid text:=current_setting('request.jwt.claim.sub',true);begin
 for p in select id,user_type from public.profiles where id=demo_session_id loop
  perform set_config('request.jwt.claim.sub',p.id::text,true);perform public.start_demo_session(p.user_type);
 end loop;
 perform set_config('request.jwt.claim.sub',coalesce(old_uid,''),true);
end $$;
commit;
select demo_session_id,count(*) as inventory_items from public.inventory_items group by 1;
select demo_session_id,bom_type,count(*) as boms from public.bom group by 1,2;
